// Never change expectations to make the current implementation pass.
const item = (anchor, fields = {}) => ({ anchor, ...fields });
const day = (items, date = '') => ({ date, items: items.map(value => typeof value === 'string' ? item(value) : value) });
const city = (name, days) => ({ name, days });
const c = (id, family, name, source, expected, note = '') => ({ id, family, name, source, expected, note });

